const NAMES = [
  'Alice Johnson',
  'Boris Petrov',
  'Carol Nguyen',
  'David Okafor',
  'Elena Sokolova',
  'Frank Miller',
];

test('filterNames matches regardless of case', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'alice'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(NAMES, 'ALICE'), ['Alice Johnson']);
  assert.deepStrictEqual(filterNames(NAMES, 'AlIcE'), ['Alice Johnson']);
});

test('filterNames matches anywhere in the name, not just the start', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'ok'), ['David Okafor', 'Elena Sokolova']);
});

test('filterNames matches on the surname', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'petrov'), ['Boris Petrov']);
});

test('filterNames returns every name for an empty or whitespace query', () => {
  assert.deepStrictEqual(filterNames(NAMES, ''), NAMES);
  assert.deepStrictEqual(filterNames(NAMES, '   '), NAMES);
});

test('filterNames treats a missing query as no filter', () => {
  assert.deepStrictEqual(filterNames(NAMES, undefined), NAMES);
  assert.deepStrictEqual(filterNames(NAMES, null), NAMES);
});

test('filterNames ignores surrounding whitespace in the query', () => {
  assert.deepStrictEqual(filterNames(NAMES, '  carol  '), ['Carol Nguyen']);
});

test('filterNames returns an empty array when nothing matches', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'zzz'), []);
});

test('filterNames preserves the original order', () => {
  assert.deepStrictEqual(filterNames(NAMES, 'o'), [
    'Alice Johnson',
    'Boris Petrov',
    'Carol Nguyen',
    'David Okafor',
    'Elena Sokolova',
  ]);
});

test('filterNames does not mutate the input array', () => {
  const input = NAMES.slice();
  filterNames(input, 'alice');
  assert.deepStrictEqual(input, NAMES);
});

test('filterNames returns a copy, not the original array reference', () => {
  const input = NAMES.slice();
  assert.notStrictEqual(filterNames(input, ''), input);
});

test('filterNames on an empty list is empty', () => {
  assert.deepStrictEqual(filterNames([], 'alice'), []);
});

