// Pure filter helper: names matching the query, case-insensitively, on any
// part of the name. A blank or missing query means "no filter". Always
// returns a new array, so callers can keep the source list intact.
function filterNames(names, query) {
  const needle = (query == null ? '' : String(query)).trim().toLowerCase();
  if (needle === '') return names.slice();
  return names.filter((name) => String(name).toLowerCase().includes(needle));
}

// Dual environment: browser (script tag, no module) + node tests (require).
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { renderList, filterNames };
}

